-- The reference tables every service reads: currencies, languages and the countries that point at
-- them. Identifiers are UUIDs generated by the database; gen_random_uuid() is built in from
-- PostgreSQL 13 onwards, so no extension is needed.
--
-- Every table carries the same five columns as com.confluo.common.jpa.entity.BaseJpaEntity:
-- the id, the two timestamps Hibernate maintains, and the two soft-state markers the services use.
-- disabled_at means "still here, not offered"; deleted_at means "gone", and rows carrying it are
-- excluded from every listing.

CREATE TABLE currencies (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    code                VARCHAR(3)      NOT NULL,
    numeric_code        VARCHAR(3)      NOT NULL,
    name                VARCHAR(255)    NOT NULL,
    symbol              VARCHAR(8)      NOT NULL,
    symbol_position     VARCHAR(8)      NOT NULL,
    minor_units         INTEGER         NOT NULL,
    CONSTRAINT uq_currencies_code UNIQUE (code),
    CONSTRAINT ck_currencies_symbol_position CHECK (symbol_position IN ('PREFIX', 'SUFFIX')),
    CONSTRAINT ck_currencies_minor_units CHECK (minor_units BETWEEN 0 AND 8)
);

CREATE TABLE languages (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    code                VARCHAR(8)      NOT NULL,
    name                VARCHAR(255)    NOT NULL,
    native_name         VARCHAR(255)    NOT NULL,
    is_right_to_left    BOOLEAN         NOT NULL,
    CONSTRAINT uq_languages_code UNIQUE (code)
);

CREATE TABLE countries (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    alpha2              VARCHAR(2)      NOT NULL,
    alpha3              VARCHAR(3)      NOT NULL,
    numeric_code        VARCHAR(3)      NOT NULL,
    name                VARCHAR(255)    NOT NULL,
    calling_code        VARCHAR(8),
    standard_vat_rate   NUMERIC(5, 2),
    is_eu_vat_member    BOOLEAN         NOT NULL,
    is_eu_member        BOOLEAN         NOT NULL,
    is_eea_member       BOOLEAN         NOT NULL,
    is_schengen_member  BOOLEAN         NOT NULL,
    default_currency_id UUID,
    default_language_id UUID,
    CONSTRAINT uq_countries_alpha2 UNIQUE (alpha2),
    CONSTRAINT uq_countries_alpha3 UNIQUE (alpha3),
    CONSTRAINT uq_countries_numeric_code UNIQUE (numeric_code),
    CONSTRAINT fk_countries_default_currency FOREIGN KEY (default_currency_id) REFERENCES currencies (id),
    CONSTRAINT fk_countries_default_language FOREIGN KEY (default_language_id) REFERENCES languages (id),
    CONSTRAINT ck_countries_vat_rate CHECK (standard_vat_rate IS NULL OR standard_vat_rate BETWEEN 0 AND 100)
);

-- The listings filter on these two constantly, and every row carries them.
CREATE INDEX ix_currencies_deleted_at ON currencies (deleted_at);
CREATE INDEX ix_languages_deleted_at ON languages (deleted_at);
CREATE INDEX ix_countries_deleted_at ON countries (deleted_at);
